with open('src/cachetools/__init__.py') as f:
    content = f.read()

# Fix the cachedmethod condition-based wrapper
old_method_cond = '''        if condition is not None:

            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                with condition:
                    try:
                        return c[k]
                    except KeyError:
                        pass  # key not found
                    # Set marker so other threads know computation is in progress
                    c[k] = _MISSING
                # Compute outside the lock
                v = method(self, *args, **kwargs)
                with condition:
                    # Wait until the value is actually stored by another thread or ourselves
                    while c.get(k) is _MISSING:
                        condition.wait()
                    try:
                        return c[k]
                    except KeyError:
                        # Value was evicted or never stored due to size constraints
                        pass
                    # Store our computed value
                    try:
                        c[k] = v
                    except ValueError:
                        return v  # value too large
                    condition.notify_all()
                    return v'''

new_method_cond = '''        if condition is not None:

            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(self, *args, **kwargs)
                with condition:
                    if k in c:
                        val = c[k]
                        if val is not _MISSING:
                            return val
                        # Key exists but computation is in progress - wait
                    else:
                        c[k] = _MISSING
                # Compute outside the lock
                v = method(self, *args, **kwargs)
                with condition:
                    # Wait until the value is actually stored by another thread or ourselves
                    while c.get(k) is _MISSING:
                        condition.wait()
                    try:
                        result = c[k]
                        if result is not _MISSING:
                            return result
                    except KeyError:
                        # Value was evicted or never stored due to size constraints
                        pass
                    # Store our computed value
                    try:
                        c[k] = v
                    except ValueError:
                        return v  # value too large
                    condition.notify_all()
                    return v'''

content = content.replace(old_method_cond, new_method_cond)

with open('src/cachetools/__init__.py', 'w') as f:
    f.write(content)

print("Fixed cachedmethod condition wrapper")
